import json, re

fpath = '/home/USER/runs/paper/qwen-h0c1-card/frozen/seen-reference/play/users/u078/system/state/sessions/01a187f9-c1f0-76be-99c1-817670c742b5.jsonl'

with open(fpath, 'r') as f:
    content = f.read()

# Extract all grid submissions with values
submissions = {}
for match in re.finditer(r'\[\[(\d+)\]\]', content):
    val = int(match.group(1))
    # Get some context around the match
    start = max(0, match.start() - 50)
    end = min(len(content), match.end() + 50)
    context = content[start:end]

    if val not in submissions:
        submissions[val] = []
    submissions[val].append(context[:100])

print("Grid value submissions found:")
for val, ctx_list in sorted(submissions.items()):
    print(f"[[{val}]] mentioned {len(ctx_list)} time(s)")

