    lines = [l.strip() for l in f.readlines() if l.strip()]

print("Checking all assistant messages for grid submissions...")

submissions_found = []

for i, line in enumerate(lines):
    try:
        data = json.loads(line)

        # Assistant message with grid action
        if data.get('type') == 'message':
            msg = data.get('message', {})
            if msg.get('role') == 'assistant':
                content_list = msg.get('content', [])

                # Check for grid in content
                for item in content_list:
                    if isinstance(item, dict) and item.get('type') == 'toolCall':
                        # Extract code from toolCall
                        code_arg = item.get('arguments', {}).get('code', '')
                        if '"action": "submit"' in code_arg.lower():
                            # Find value - search for [[X]] pattern or grid
                            import re
                            val_match = re.search(r'\[\[(\d+)\]\]', code_arg)
                            if not val_match:
                                grid_match = re.search(r'"grid"\s*:\s*\[\s*\[\s*(\d+)', code_arg)
                                if grid_match:
                                    val = int(grid_match.group(1))
                                    submissions_found.append((i, val))
                    elif isinstance(item, dict) and item.get('type') == 'thinking':
                        thinking = item.get('thinking', '')
                        val_match = re.search(r'Submitted.*?\[\[([0-9]+)\]\]', thinking)
                        if val_match:
                            val = int(val_match.group(1))
                            submissions_found.append((i, val))

    except:
        pass

print(f"\nFound {len(submissions_found)} submissions:")
for line_num, val in reversed(submissions_found[-10:]):
